<div class="setup-advanced-grid"><div><label for="volunteer-scope">Where should it help?</label><select id="volunteer-scope" name="scope_kind"><?php if(!in_array($scopeKind,['all','category','research'],true)): ?><option value="<?=e($scopeKind)?>" selected><?=e($scopeKind)?></option><?php endif ?><?php foreach(['all'=>'Wherever needed','category'=>'A topic or category','research'=>'One research question'] as $value=>$label): ?><option value="<?=e($value)?>" <?=$scopeKind===$value?'selected':''?>><?=e($label)?></option><?php endforeach ?></select></div>
<div><label for="volunteer-capabilities">AI capabilities</label><select id="volunteer-capabilities" name="session_profile"><?php if(!isset(VS_PROFILES[$draft['session_profile']])): ?><option value="<?=e($draft['session_profile'])?>" selected><?=e($draft['session_profile'])?></option><?php endif ?><?php foreach(['general'=>'Research + tools','restricted_web_v1'=>'Research only'] as $id=>$label): ?><option value="<?=e($id)?>" <?=$draft['session_profile']===$id?'selected':''?>><?=e($label)?></option><?php endforeach ?></select></div>
<div class="setup-scope-field" data-volunteer-scope="category"><label for="volunteer-category">Category</label><select id="volunteer-category" name="category_id"><option value="">Choose a category</option><?php if($categoryId!==''&&!in_array((string)$categoryId,array_map(fn($item)=>(string)$item['id'],$categories),true)): ?><option value="<?=e($categoryId)?>" selected><?=e($categoryId)?></option><?php endif ?><?php foreach($categories as $category): ?><option value="<?=e($category['id'])?>" <?=(string)$categoryId===(string)$category['id']?'selected':''?>><?=e($category['name'])?></option><?php endforeach ?></select></div>
<div class="setup-scope-field" data-volunteer-scope="research"><label for="volunteer-research">Public research ID or readable URL name</label><input id="volunteer-research" name="research_id" maxlength="180" value="<?=e($draft['research_id']??'')?>"></div></div>
<fieldset class="setup-custom-limits"><legend>Custom limits<span data-custom-active <?=$preset==='custom'?'':'hidden'?>> · Custom</span></legend><div class="setup-advanced-grid"><div><label for="volunteer-minutes">Session minutes</label><input id="volunteer-minutes" type="number" name="minutes" min="5" max="240" value="<?=e($draft['minutes'])?>"></div><div><label for="volunteer-count">Task assignments</label><input id="volunteer-count" type="number" name="assignment_limit" min="1" max="20" value="<?=e($draft['assignment_limit'])?>"></div></div><label class="setup-native-custom"><input type="radio" name="session_preset" value="custom" <?=$preset==='custom'?'checked':''?>> Use custom limits</label></fieldset>
<div class="setup-advanced-grid setup-worker-options"><div><label for="volunteer-tool">AI tool or harness name</label><input id="volunteer-tool" name="tool" maxlength="100" value="<?=e($draft['tool'])?>"></div><div><label for="volunteer-mode">Workflow mode</label><select id="volunteer-mode" name="workflow_mode"><?php if(!in_array($draft['workflow_mode'],['','ultracode'],true)): ?><option value="<?=e($draft['workflow_mode'])?>" selected><?=e($draft['workflow_mode'])?></option><?php endif ?><option value="">No specific mode</option><option value="ultracode" <?=$draft['workflow_mode']==='ultracode'?'selected':''?>>Ultracode</option></select></div><div><label for="concurrent-limit">Tasks at the same time</label><select id="concurrent-limit" name="concurrent_limit"><?php if(!in_array((string)$draft['concurrent_limit'],['1','2','3'],true)): ?><option value="<?=e($draft['concurrent_limit'])?>" selected><?=e($draft['concurrent_limit'])?></option><?php endif ?><?php foreach([1,2,3] as $limit): ?><option value="<?=$limit?>" <?=(int)$draft['concurrent_limit']===$limit?'selected':''?>><?=$limit?></option><?php endforeach ?></select></div></div>
